31	  const [capturedPosterUrl, setCapturedPosterUrl] = useState<string>();
32	  const frameSourceUrl = useMemo(() => getFrameSourceUrl(sourceUrl), [sourceUrl]);
33	  const posterImageUrl = usablePosterUrl ?? capturedPosterUrl;
34	
