13	const getFrameSourceUrl = (sourceUrl: string): string => {
14	  if (!sourceUrl || sourceUrl.startsWith("blob:") || sourceUrl.startsWith("data:") || sourceUrl.includes("#")) {
15	    return sourceUrl;
16	  }
17	
18	  return `${sourceUrl}#t=0.001`;
19	};
20	
21	const getCanvasSize = (width: number, height: number) => {
22	  const scale = Math.min(1, MAX_POSTER_DIMENSION / Math.max(width, height));
23	  return {
24	    width: Math.max(1, Math.round(width * scale)),
25	    height: Math.max(1, Math.round(height * scale)),
26	  };
27	};
28	
29	const VideoPoster = ({ sourceUrl, alt, className, posterUrl }: VideoPosterProps) => {
30	  const usablePosterUrl = posterUrl && posterUrl !== sourceUrl ? posterUrl : undefined;
31	  const [capturedPosterUrl, setCapturedPosterUrl] = useState<string>();
32	  const frameSourceUrl = useMemo(() => getFrameSourceUrl(sourceUrl), [sourceUrl]);
33	  const posterImageUrl = usablePosterUrl ?? capturedPosterUrl;
34	
35	  useEffect(() => {
36	    setCapturedPosterUrl(undefined);
37	  }, [sourceUrl, usablePosterUrl]);
38	
39	  const captureFrame = useCallback(
40	    (video: HTMLVideoElement) => {
41	      if (usablePosterUrl || capturedPosterUrl || video.videoWidth <= 0 || video.videoHeight <= 0) {
42	        return;
43	      }
44	
45	      try {
46	        const { width, height } = getCanvasSize(video.videoWidth, video.videoHeight);
47	        const canvas = document.createElement("canvas");
48	        canvas.width = width;
49	        canvas.height = height;
50	
51	        const context = canvas.getContext("2d");
52	        if (!context) {
53	          return;
54	        }
55	
56	        context.drawImage(video, 0, 0, width, height);
57	        setCapturedPosterUrl(canvas.toDataURL("image/jpeg", 0.86));
58	      } catch {
59	        // Cross-origin or codec-specific failures should keep the video fallback visible.
60	      }
61	    },
62	    [capturedPosterUrl, usablePosterUrl],
63	  );
